/*
 * prog38_continued_fraction.c
 *
 * Re‑implementation of the original program (identified as
 * prog38_continued_fraction) based on the reverse‑engineered state
 * machine.  The program reads two decimal integers from the command line,
 * computes the simple continued‑fraction expansion of the rational number
 *   a / b
 * and prints it in the usual bracketed form:
 *
 *     [q0; q1, q2, q3, ...]
 *
 * The original binary performed a number of sanity checks and printed
 * specific error messages.  All those checks are reproduced exactly so
 * that the observable output (stdout) matches the original binary for
 * every possible input.
 *
 * Behaviour summary
 * -----------------
 *  * If fewer than two arguments are supplied:          prints "NO_INPUT"
 *  * If either argument is not a valid decimal integer: prints "BAD_INPUT"
 *  * If the denominator is zero:                        prints "BAD_INPUT"
 *  * If the absolute value of the denominator exceeds 100 000:
 *                                                       prints "OUT_OF_RANGE"
 *  * If the continued‑fraction expansion would need more than
 *    199 terms:                                         prints "ERROR"
 *  * Otherwise prints the expansion in the form described
 *    above, using '[' and ']' as delimiters, '; ' after the
 *    first term and ', ' between the remaining terms.
 *
 * The implementation follows the same algorithmic steps as the
 * original (Euclidean algorithm) and respects the same limits.
 */

#include <stdio.h>
#include <stdlib.h>
#include <errno.h>
#include <limits.h>

#define MAX_TERMS 200          /* one more than the allowed 199 */
#define OUT_OF_RANGE_LIMIT 100000L

int main(int argc, char **argv)
{
    /* ---------- argument count check ---------- */
    if (argc < 3) {
        puts("NO_INPUT");
        return 0;
    }

    /* ---------- parse the two numbers ---------- */
    char *end1, *end2;
    errno = 0;
    long long num = strtoll(argv[1], &end1, 10);
    long long den = strtoll(argv[2], &end2, 10);

    /* parsing must consume the whole argument and must not overflow */
    if (errno != 0 ||
        *end1 != '\0' || *end2 != '\0' ||
        end1 == argv[1] || end2 == argv[2]) {
        puts("BAD_INPUT");
        return 0;
    }

    /* ---------- denominator checks ---------- */
    if (den == 0) {
        puts("BAD_INPUT");
        return 0;
    }
    if (llabs(den) > OUT_OF_RANGE_LIMIT) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    /* ---------- compute continued fraction ---------- */
    long long a = num;
    long long b = den;
    long long terms[MAX_TERMS];
    int n = 0;

    while (b != 0) {
        if (n >= 199) {               /* more than 199 terms is an error */
            puts("ERROR");
            return 0;
        }
        long long q = a / b;          /* integer division, truncates toward 0 */
        terms[n++] = q;
        long long r = a - q * b;      /* remainder */
        a = b;
        b = r;
    }

    /* ---------- output the fraction ---------- */
    putchar('[');
    for (int i = 0; i < n; ++i) {
        if (i == 0) {
            /* first term – nothing before it */
        } else if (i == 1) {
            printf("; ");
        } else {
            printf(", ");
        }
        printf("%lld", terms[i]);
    }
    putchar(']');

    return 0;
}
